WITH unpivoted AS (SELECT * FROM (SELECT id, channel, discount, shipping_fee, amount FROM orders) src UNPIVOT (val FOR metric IN (discount, shipping_fee, amount)) u) SELECT CASE WHEN val >= 87 THEN 'PREMIUM' ELSE 'STANDARD' END AS val_tier, COUNT(*) AS num_rows, COUNT(CASE WHEN metric = 'amount' THEN 1 END) AS amount_count, SUM(CASE WHEN metric = 'discount' THEN val ELSE 0 END) AS discount_val, SIZE(COLLECT_SET(metric)) AS num_metrics FROM unpivoted GROUP BY CASE WHEN val >= 87 THEN 'PREMIUM' ELSE 'STANDARD' END HAVING COUNT(CASE WHEN metric = 'amount' THEN 1 END) > 1;
